<?php
declare(strict_types=1);
require_once __DIR__ . '/auth.php';
require_roles(['super_admin', 'admin']);
require_once __DIR__ . '/config/database.php';
$pdo = database_connection();
$error = ''; $success = '';
function school_h(mixed $v): string { return htmlspecialchars((string)$v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function school_post_id(string $key): int { $v = filter_var($_POST[$key] ?? null, FILTER_VALIDATE_INT); return $v && $v > 0 ? $v : 0; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
 if (!csrf_token_is_valid($_POST['csrf_token'] ?? null)) { http_response_code(400); exit('Invalid form token. Refresh and retry.'); }
 try {
  $action = (string)($_POST['action'] ?? '');
  if ($action === 'year') {
   $name=trim((string)($_POST['name']??'')); $start=(string)($_POST['starts_on']??''); $end=(string)($_POST['ends_on']??'');
   if ($name==='' || mb_strlen($name)>40) throw new RuntimeException('نام سال تحصیلی الزامی است.');
   if ($start!=='' && $end!=='' && $end<$start) throw new RuntimeException('تاریخ پایان باید بعد از تاریخ شروع باشد.');
   $pdo->prepare('INSERT INTO school_years(name,starts_on,ends_on) VALUES(?,?,?)')->execute([$name,$start?:null,$end?:null]);
   $success='سال تحصیلی ساخته شد.';
  } elseif ($action === 'activate_year') {
   $id=school_post_id('year_id'); if(!$id) throw new RuntimeException('سال تحصیلی معتبر نیست.');
   $pdo->beginTransaction(); $pdo->exec('UPDATE school_years SET is_active=0');
   $st=$pdo->prepare('UPDATE school_years SET is_active=1,is_closed=0 WHERE id=?'); $st->execute([$id]);
   if(!$st->rowCount()) throw new RuntimeException('سال تحصیلی پیدا نشد.');
   $pdo->commit(); $success='سال تحصیلی فعال شد.';
  } elseif ($action === 'close_year') {
   $id=school_post_id('year_id'); if(!$id) throw new RuntimeException('سال تحصیلی معتبر نیست.');
   $pdo->prepare('UPDATE school_years SET is_closed=1,is_active=0 WHERE id=?')->execute([$id]); $success='سال تحصیلی بسته شد.';
  } elseif ($action === 'teacher') {
   $name=trim((string)($_POST['full_name']??'')); $phone=trim((string)($_POST['phone']??'')); $email=trim((string)($_POST['email']??''));
   if($name==='' || mb_strlen($name)>200) throw new RuntimeException('نام آموزگار الزامی است.');
   $pdo->prepare('INSERT INTO teachers(full_name,phone,email) VALUES(?,?,?)')->execute([$name,$phone,$email]); $success='آموزگار ثبت شد.';
  } elseif ($action === 'section') {
   $year=school_post_id('school_year_id'); $grade=school_post_id('grade'); $section=trim((string)($_POST['section_name']??'')); $teacher=school_post_id('teacher_id');
   $st=$pdo->prepare('SELECT is_closed FROM school_years WHERE id=?'); $st->execute([$year]); $yr=$st->fetch();
   if(!$yr || (int)$yr['is_closed']===1) throw new RuntimeException('سال تحصیلی انتخاب‌شده معتبر یا باز نیست.');
   if($grade<1 || $grade>12 || $section==='') throw new RuntimeException('پایه باید بین ۱ تا ۱۲ و نام صنف الزامی است.');
   $pdo->prepare('INSERT INTO class_sections(school_year_id,grade,section_name,teacher_id) VALUES(?,?,?,?)')->execute([$year,$grade,$section,$teacher?:null]); $success='صنف ثبت شد.';
  } elseif ($action === 'assign' || $action === 'transfer') {
   $student=school_post_id('student_id'); $section=school_post_id('class_section_id'); $note=trim((string)($_POST['notes']??''));
   $st=$pdo->prepare('SELECT cs.id,cs.school_year_id,cs.grade,sy.is_closed FROM class_sections cs JOIN school_years sy ON sy.id=cs.school_year_id WHERE cs.id=? AND cs.is_active=1'); $st->execute([$section]); $dest=$st->fetch();
   if(!$student || !$dest || (int)$dest['is_closed']===1) throw new RuntimeException('دانش‌آموز یا صنف معتبر نیست، یا سال بسته است.');
   $st=$pdo->prepare('SELECT id,class_section_id FROM student_enrollments WHERE student_id=? AND school_year_id=? AND is_current=1 ORDER BY id DESC LIMIT 1'); $st->execute([$student,$dest['school_year_id']]); $old=$st->fetch();
   if($action==='assign' && $old) throw new RuntimeException('این دانش‌آموز در همین سال قبلاً صنف دارد؛ برای تغییر صنف از انتقال استفاده کنید.');
   if($action==='transfer' && !$old) throw new RuntimeException('برای این سال ثبت‌نام فعالی پیدا نشد؛ ابتدا دانش‌آموز را ثبت کنید.');
   if($old && (int)$old['class_section_id']===$section) throw new RuntimeException('دانش‌آموز از قبل در همین صنف است.');
   $pdo->beginTransaction();
   if($old) {
    $pdo->prepare("UPDATE student_enrollments SET class_section_id=?,status='transferred',notes=? WHERE id=?")->execute([$section,$note,$old['id']]);
    $kind='transferred'; $from=(int)$old['class_section_id']; $enrollment=(int)$old['id'];
   } else {
    $pdo->prepare("INSERT INTO student_enrollments(student_id,school_year_id,class_section_id,status,notes) VALUES(?,?,?,'enrolled',?)")->execute([$student,$dest['school_year_id'],$section,$note]);
    $enrollment=(int)$pdo->lastInsertId(); $kind='assigned'; $from=null;
   }
   $pdo->prepare('INSERT INTO student_enrollment_history(enrollment_id,student_id,school_year_id,from_section_id,to_section_id,changed_by,change_type,notes) VALUES(?,?,?,?,?,?,?,?)')->execute([$enrollment,$student,$dest['school_year_id'],$from,$section,(int)$_SESSION['user_id'],$kind,$note]);
   $pdo->commit(); $success=$kind==='assigned'?'ثبت‌نام در صنف انجام شد.':'انتقال انجام شد و در تاریخچه ثبت شد.';
  } elseif ($action === 'promote') {
   $fromYear=school_post_id('from_year'); $toSection=school_post_id('to_section'); $student=school_post_id('student_id');
   $st=$pdo->prepare('SELECT cs.school_year_id,cs.grade,sy.is_closed FROM class_sections cs JOIN school_years sy ON sy.id=cs.school_year_id WHERE cs.id=?'); $st->execute([$toSection]); $dest=$st->fetch();
   $st=$pdo->prepare('SELECT e.*,cs.grade AS old_grade FROM student_enrollments e JOIN class_sections cs ON cs.id=e.class_section_id WHERE e.student_id=? AND e.school_year_id=? AND e.is_current=1'); $st->execute([$student,$fromYear]); $old=$st->fetch();
   if(!$old || !$dest || (int)$dest['is_closed']===1 || (int)$dest['school_year_id']===$fromYear) throw new RuntimeException('ثبت‌نام قبلی یا صنف سال بعد معتبر نیست.');
   if((int)$old['old_grade']>=12 || (int)$dest['grade'] !== (int)$old['old_grade']+1) throw new RuntimeException('برای ارتقا باید صنف مقصد دقیقاً یک پایه بالاتر باشد.');
   $pdo->beginTransaction();
   $pdo->prepare("UPDATE student_enrollments SET is_current=0,status='promoted',ended_at=NOW() WHERE id=?")->execute([$old['id']]);
   $pdo->prepare("INSERT INTO student_enrollments(student_id,school_year_id,class_section_id,status,notes) VALUES(?,?,?,'enrolled','Promoted from previous school year')")->execute([$student,$dest['school_year_id'],$toSection]);
   $newId=(int)$pdo->lastInsertId();
   $pdo->prepare("INSERT INTO student_enrollment_history(enrollment_id,student_id,school_year_id,from_section_id,to_section_id,changed_by,change_type,notes) VALUES(?,?,?,?,?,?,'promoted',?)")->execute([$newId,$student,$dest['school_year_id'],$old['class_section_id'],$toSection,(int)$_SESSION['user_id'],'Promotion from school year '.$fromYear]);
   $pdo->commit(); $success='دانش‌آموز به سال تحصیلی جدید منتقل شد و تاریخچه حفظ شد.';
  } else { throw new RuntimeException('عملیات نامعتبر است.'); }
 } catch (Throwable $e) {
  if($pdo->inTransaction()) $pdo->rollBack();
  if($e instanceof PDOException && $e->getCode()==='23000') $error='این مورد تکراری است یا به اطلاعات موجود وابسته است.';
  else { $error=$e instanceof RuntimeException ? $e->getMessage() : 'عملیات انجام نشد. ابتدا migration را اجرا کنید.'; if(!$e instanceof RuntimeException) error_log('School management: '.$e->getMessage()); }
 }
}
$years=$pdo->query('SELECT * FROM school_years ORDER BY starts_on DESC,id DESC')->fetchAll();
$teachers=$pdo->query('SELECT * FROM teachers WHERE is_active=1 ORDER BY full_name')->fetchAll();
$sections=$pdo->query('SELECT cs.*,sy.name AS year_name,sy.is_closed,t.full_name AS teacher_name FROM class_sections cs JOIN school_years sy ON sy.id=cs.school_year_id LEFT JOIN teachers t ON t.id=cs.teacher_id ORDER BY sy.id DESC,cs.grade,cs.section_name')->fetchAll();
$students=$pdo->query('SELECT id,student_number,first_name,last_name FROM students WHERE is_active=1 ORDER BY last_name,first_name LIMIT 1000')->fetchAll();
$enrollments=$pdo->query("SELECT e.id,e.student_id,e.school_year_id,e.class_section_id,e.status,s.student_number,s.first_name,s.last_name,sy.name AS year_name,cs.grade,cs.section_name FROM student_enrollments e JOIN students s ON s.id=e.student_id JOIN school_years sy ON sy.id=e.school_year_id JOIN class_sections cs ON cs.id=e.class_section_id WHERE e.is_current=1 ORDER BY sy.id DESC,cs.grade,cs.section_name,s.last_name LIMIT 500")->fetchAll();
$history=$pdo->query("SELECT h.changed_at,h.change_type,h.notes,s.student_number,s.first_name,s.last_name,fy.name AS year_name,fs.grade AS from_grade,fs.section_name AS from_section,ts.grade AS to_grade,ts.section_name AS to_section,u.username FROM student_enrollment_history h JOIN students s ON s.id=h.student_id JOIN school_years fy ON fy.id=h.school_year_id LEFT JOIN class_sections fs ON fs.id=h.from_section_id JOIN class_sections ts ON ts.id=h.to_section_id LEFT JOIN users u ON u.id=h.changed_by ORDER BY h.id DESC LIMIT 100")->fetchAll();
?>
