.school-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:18px}.school-card{background:#fff;border:1px solid #e1e7f0;border-radius:14px;padding:18px;margin-bottom:18px}.school-card h2{font-size:19px;margin:0 0 14px}.school-card label{display:block;margin:10px 0 5px;font-weight:700}.school-card input,.school-card select,.school-card textarea{width:100%;padding:10px;border:1px solid #ccd5e2;border-radius:8px;font:inherit;min-height:42px}.school-card button{margin-top:12px}.school-table{width:100%;border-collapse:collapse}.school-table th,.school-table td{padding:10px;border-bottom:1px solid #e5eaf1;text-align:right;white-space:nowrap}.school-table-wrap{overflow:auto}.school-alert{padding:12px;border-radius:9px;margin-bottom:14px;background:#edf8ef}.school-error{background:#fff0f0}.school-muted{color:#667085;font-size:13px}@media(max-width:700px){.school-card{padding:12px}}
</style></head><body class="profile-page"><div class="admin-layout"><aside class="admin-sidebar" id="admin-sidebar"><button type="button" class="sidebar-toggle" id="sidebar-toggle" aria-controls="admin-sidebar" aria-expanded="false"><span class="sidebar-toggle-icon">☰</span><span class="sidebar-toggle-label">منو</span></button><a class="sidebar-brand" href="dashboard.php"><span class="sidebar-brand-mark">م‌د</span><span><strong>پنل مدیریت</strong><small>سامانه مدیریت دانش‌آموزان</small></span></a><p class="sidebar-section-label">منوی اصلی</p><nav class="sidebar-nav"><a class="sidebar-link" href="dashboard.php">داشبورد</a><a class="sidebar-link" href="students.php">مدیریت دانش‌آموزان</a><a class="sidebar-link is-current" href="school.php">سال تحصیلی و صنف‌ها</a><a class="sidebar-link" href="users.php">مدیریت کاربران</a></nav><div class="sidebar-bottom"><div class="sidebar-user-copy"><strong><?=school_h($_SESSION['username'])?></strong></div><form action="logout.php" method="post"><input type="hidden" name="csrf_token" value="<?=school_h(csrf_token())?>"><button class="sidebar-logout" type="submit">خروج</button></form></div></aside><main class="admin-main"><header class="page-header"><div><p class="eyebrow">تنظیمات مدرسه</p><h1>سال تحصیلی، صنف‌ها و ثبت‌نام</h1><p class="muted">پایه‌های ۱ تا ۱۲، آموزگاران، انتقال دانش‌آموز و حفظ تاریخچه</p></div></header>
<?php if($success!==''):?><div class="school-alert"><?=school_h($success)?></div><?php endif;?><?php if($error!==''):?><div class="school-alert school-error"><?=school_h($error)?></div><?php endif;?>
<div class="school-grid"><section class="school-card"><h2>ساخت سال تحصیلی</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=school_h(csrf_token())?>"><input type="hidden" name="action" value="year"><label>نام سال تحصیلی</label><input name="name" required placeholder="مثلاً ۱۴۰۵-۱۴۰۶"><label>تاریخ شروع</label><input type="date" name="starts_on"><label>تاریخ پایان</label><input type="date" name="ends_on"><button class="button button-primary">ثبت سال</button></form><h2 style="margin-top:22px">سال‌های ثبت‌شده</h2><?php foreach($years as $y):?><div style="padding:9px 0;border-bottom:1px solid #eee"><strong><?=school_h($y['name'])?></strong> — <?=$y['is_active']?'فعال':($y['is_closed']?'بسته':'غیرفعال')?> <form method="post" style="display:inline"><input type="hidden" name="csrf_token" value="<?=school_h(csrf_token())?>"><input type="hidden" name="year_id" value="<?=$y['id']?>"><button name="action" value="activate_year" class="button button-secondary">فعال‌سازی</button><button name="action" value="close_year" class="button button-secondary">بستن</button></form></div><?php endif; endforeach;?></section>
<section class="school-card"><h2>ثبت آموزگار</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=school_h(csrf_token())?>"><input type="hidden" name="action" value="teacher"><label>نام کامل</label><input name="full_name" required><label>تلفن</label><input name="phone"><label>ایمیل</label><input type="email" name="email"><button class="button button-primary">ثبت آموزگار</button></form><h2 style="margin-top:22px">ساخت صنف</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=school_h(csrf_token())?>"><input type="hidden" name="action" value="section"><label>سال تحصیلی</label><select name="school_year_id" required><option value="">انتخاب سال</option><?php foreach($years as $y): if(!$y['is_closed']):?><option value="<?=$y['id']?>"><?=school_h($y['name'])?></option><?php endif;?></select><label>پایه</label><select name="grade" required><?php for($g=1;$g<=12;$g++):?><option value="<?=$g?>">پایه <?=$g?></option><?php endfor;?></select><label>نام بخش / صنف</label><input name="section_name" required placeholder="الف، ب، ج"><label>آموزگار مسئول</label><select name="teacher_id"><option value="">بدون آموزگار</option><?php foreach($teachers as $t):?><option value="<?=$t['id']?>"><?=school_h($t['full_name'])?></option><?php endif; endforeach;?></select><button class="button button-primary">ساخت صنف</button></form></section>
<section class="school-card"><h2>ثبت‌نام دانش‌آموز در صنف</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=school_h(csrf_token())?>"><input type="hidden" name="action" value="assign"><label>دانش‌آموز</label><select name="student_id" required><option value="">انتخاب دانش‌آموز</option><?php foreach($students as $s):?><option value="<?=$s['id']?>"><?=school_h($s['student_number'].' — '.$s['first_name'].' '.$s['last_name'])?></option><?php endif; endforeach;?></select><label>صنف</label><select name="class_section_id" required><option value="">انتخاب صنف</option><?php foreach($sections as $s): if($s['is_active']):?><option value="<?=$s['id']?>"><?=school_h($s['year_name'].' — پایه '.$s['grade'].' '.$s['section_name'])?></option><?php endif; endforeach;?></select><label>یادداشت</label><textarea name="notes"></textarea><button class="button button-primary">ثبت‌نام</button></form></section>
<section class="school-card"><h2>انتقال دانش‌آموز بین صنف‌ها</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=school_h(csrf_token())?>"><input type="hidden" name="action" value="transfer"><label>دانش‌آموز</label><select name="student_id" required><option value="">انتخاب دانش‌آموز</option><?php foreach($students as $s):?><option value="<?=$s['id']?>"><?=school_h($s['student_number'].' — '.$s['first_name'].' '.$s['last_name'])?></option><?php endif; endforeach;?></select><label>صنف جدید در همان سال تحصیلی</label><select name="class_section_id" required><option value="">انتخاب صنف</option><?php foreach($sections as $s): if($s['is_active']&&!$s['is_closed']):?><option value="<?=$s['id']?>"><?=school_h($s['year_name'].' — پایه '.$s['grade'].' '.$s['section_name'])?></option><?php endif; endforeach;?></select><label>دلیل / یادداشت</label><textarea name="notes"></textarea><button class="button button-primary">انتقال</button></form></section>
<section class="school-card"><h2>ارتقای دانش‌آموز به سال بعد</h2><p class="school-muted">دانش‌آموز باید برای سال فعلی ثبت‌نام فعال داشته باشد. ارتقا یک رکورد جدید برای سال مقصد می‌سازد و سابقه قبلی را نگه می‌دارد. انتخاب قبولی را پیش از ارتقا بررسی کنید.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=school_h(csrf_token())?>"><input type="hidden" name="action" value="promote"><label>دانش‌آموز</label><select name="student_id" required><option value="">انتخاب دانش‌آموز</option><?php foreach($students as $s):?><option value="<?=$s['id']?>"><?=school_h($s['student_number'].' — '.$s['first_name'].' '.$s['last_name'])?></option><?php endif; endforeach;?></select><label>سال فعلی</label><select name="from_year" required><option value="">انتخاب سال</option><?php foreach($years as $y):?><option value="<?=$y['id']?>"><?=school_h($y['name'])?></option><?php endif; endforeach;?></select><label>صنف در سال جدید</label><select name="to_section" required><option value="">انتخاب صنف مقصد</option><?php foreach($sections as $s): if(!$s['is_closed']):?><option value="<?=$s['id']?>"><?=school_h($s['year_name'].' — پایه '.$s['grade'].' '.$s['section_name'])?></option><?php endif; endforeach;?></select><button class="button button-primary">ارتقا / ثبت در سال جدید</button></form></section></div>
<section class="school-card"><h2>صنف‌ها و آموزگاران</h2><div class="school-table-wrap"><table class="school-table"><thead><tr><th>سال</th><th>پایه</th><th>بخش</th><th>آموزگار مسئول</th><th>وضعیت</th></tr></thead><tbody><?php foreach($sections as $s):?><tr><td><?=school_h($s['year_name'])?></td><td><?=$s['grade']?></td><td><?=school_h($s['section_name'])?></td><td><?=school_h($s['teacher_name']??'تعیین نشده')?></td><td><?=$s['is_active']?'فعال':'غیرفعال'?></td></tr><?php endif; endforeach;?></tbody></table></div></section>
<section class="school-card"><h2>ثبت‌نام‌های فعلی</h2><div class="school-table-wrap"><table class="school-table"><thead><tr><th>شماره</th><th>دانش‌آموز</th><th>سال</th><th>پایه</th><th>بخش</th></tr></thead><tbody><?php foreach($enrollments as $e):?><tr><td><?=school_h($e['student_number'])?></td><td><?=school_h($e['first_name'].' '.$e['last_name'])?></td><td><?=school_h($e['year_name'])?></td><td><?=$e['grade']?></td><td><?=school_h($e['section_name'])?></td></tr><?php endif; endforeach;?></tbody></table></div></section>
<section class="school-card"><h2>تاریخچه انتقال و ارتقا</h2><div class="school-table-wrap"><table class="school-table"><thead><tr><th>زمان</th><th>دانش‌آموز</th><th>سال</th><th>از صنف</th><th>به صنف</th><th>عملیات</th><th>کاربر</th><th>یادداشت</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td><?=school_h($h['changed_at'])?></td><td><?=school_h($h['student_number'].' — '.$h['first_name'].' '.$h['last_name'])?></td><td><?=school_h($h['year_name'])?></td><td><?= $h['from_grade'] ? school_h($h['from_grade'].' '.$h['from_section']) : '—' ?></td><td><?=school_h($h['to_grade'].' '.$h['to_section'])?></td><td><?=school_h($h['change_type'])?></td><td><?=school_h($h['username']??'—')?></td><td><?=school_h($h['notes'])?></td></tr><?php endif; endforeach;?></tbody></table></div></section>
</main></div><script src="assets/js/app.js"></script></body></html>
